"""Review individually selected flags in surahs 9–18."""
import argparse
from semantic_review import ReviewBatch, validate


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()
    b = ReviewBatch("semantic-review-006", "Selected location-specific relative, temporal, modal and nominal relations through surah 18; broader interpretive issues remain explicitly limited.")
