    d("10:37:7 10:37:8 10:37:9", "Retain the inspected passive-agent phrase Allah'tan başkası tarafından: min contributes the agent relation, dun the other-than relation, and Allah the named excluded party. These complementary displays preserve the whole passive agent construction.", True)
    p("10:37", "previous-scripture", [("kendisin",14),("den önce",13),("kini",12)], "Alladhi bayna yadayhi denotes what preceded it, not a physical object between two hands. Restore the anterior scripture reference and its relative object ending.")
    d("10:37:12", "Restore the idiomatic anterior meaning rather than a literal hands-between gloss.")
    p("10:45", "negative-guidance", [("ve ",18),("doğru yolu bulmuş",20),(" değil",18),("lerdi",19)], "Wa-ma kanu muhtadina is a negative past guidance predication. Restore negation at ma and the past copula at kanu rather than conceal both inside girmeyenler.")
    d("10:45:19", "Restore the finite negative past predicate, not an independently nominal list of unguided people.")
    p("10:61", "any-deed", [("herhangi bir ",12),("iş",13)], "Min amalin identifies any deed in the surrounding no-action-except-witnessing construction. Remove the invented future yapılacaklar and its source ending; the governing Turkish ne ... yapsanız frame needs an uninflected object.")
