    c("13:11", "changing-predicate", {14:"(değiştir)mez",15:"değiştir(mez)"}, "The state/content is now explicitly supplied by ma; remove its duplicated bracketed object from the changing predicate.")
    p("13:11", "inner-state", [("kendi içlerinde ",21),("olanı",20)], "Ma bi-anfusihim identifies what is within themselves. Expose the nominal-relative content at ma and the pronominal inward relation at bi-anfusihim.")
    p("13:11", "no-protector", [("hiçbir ",34),("koruyucuları",35)], "Min walin under negation marks any protector; restore the indefinite scope instead of copying the protector noun.")
